/******************************************************
 * Airtable Automation Script
 * Sends SMS reply data to n8n webhook
 * https://n8n.dulcy.io/webhook/REDACTED_PATH
 *
 * REQUIRED input variables:
 * - sentFromNumber
 * - phoneNumber
 * - customReply
 ******************************************************/

const inputData = input.config();

// ---- DEBUG (keep while testing)
console.log("RAW inputData:", JSON.stringify(inputData, null, 2));

// ---- REQUIRED VARIABLES
const sentFromNumber = inputData.sentFromNumber;
const phoneNumber = inputData.phoneNumber;
const customReply = inputData.customReply;

// ---- HARD VALIDATION
if (!sentFromNumber) throw new Error("Missing sentFromNumber.");
if (!phoneNumber) throw new Error("Missing phoneNumber.");
if (!customReply) throw new Error("Missing customReply.");

// ---- WEBHOOK
const webhookUrl = "https://n8n.dulcy.io/webhook/REDACTED_PATH";

const payload = {
  sentFromNumber: String(sentFromNumber).trim(),
  phoneNumber: String(phoneNumber).trim(),
  customReply: String(customReply),
};

console.log("SENDING payload:", JSON.stringify(payload, null, 2));

const response = await fetch(webhookUrl, {
  method: "POST",
  headers: {
    "Content-Type": "application/json",
    "Accept": "application/json, text/plain, */*",
  },
  body: JSON.stringify(payload),
});

const text = await response.text();

console.log("STATUS:", response.status);
console.log("RESPONSE:", text);

if (!response.ok) {
  throw new Error(`Webhook error ${response.status}: ${text}`);
}

// ---- SUCCESS
return {
  ok: true,
  status: response.status,
  response: text,
  sentBody: payload,
};
